DROP TABLE IF EXISTS activities;
DROP TABLE IF EXISTS comments;
DROP TABLE IF EXISTS tasks;
DROP TABLE IF EXISTS projects;
DROP TABLE IF EXISTS memberships;
DROP TABLE IF EXISTS organizations;
DROP TABLE IF EXISTS users;
CREATE TABLE users (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, auth_subject TEXT UNIQUE, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE organizations (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, name TEXT NOT NULL, owner_id TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE memberships (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,user_id)) STRICT;
CREATE TABLE projects (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE tasks (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, creator_id TEXT NOT NULL, assignee_id TEXT, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, due_date TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE comments (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, task_id TEXT NOT NULL, author_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE activities (id INTEGER PRIMARY KEY, external_id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, project_id TEXT, actor_id TEXT NOT NULL, action TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE INDEX tasks_tenant_idx ON tasks(organization_id, project_id, created_at, id);
CREATE INDEX comments_task_idx ON comments(organization_id, project_id, task_id, created_at, id);
CREATE INDEX activities_project_idx ON activities(organization_id, project_id, created_at, id);
